## Product Schema

```js
/** @type {Enterspeed.FullSchema} */
export default {
  triggers: function (context) {
    context.triggers('pim', ["product"]);
  },
  routes: function (sourceEntity, context) {
      // See documentation for routes here: https://docs.enterspeed.com/reference/js/full-schema/routes
      context.url(sourceEntity.url)
  },
  properties: function (sourceEntity, context) {   
    return { 
      ...sourceEntity.properties,
      originId: sourceEntity.originId,
      type: sourceEntity.type,
      productMetadata: context.reference('productMetadata').byOriginId(`${sourceEntity.originId}-metadata`) ?? ""
    }
  }
};

```

## Product-Metadata Schema

```js
/** @type {Enterspeed.FullSchema} */
export default {
  triggers: function(context) {
    context.triggers('pim', ['enricedProductMetadata'])
  },
  properties: function (sourceEntity, context) {
    return sourceEntity.properties
  }
}

```

