const out = [];

for (const item of $input.all()) {
  const route = item.json.route ?? {};

  // Namespace the id so we don't overwrite the original source entity.
  const originId = `${route.originId}-metadata`;

  const properties = {
    seoMetaDescription: "Discover 'The Flying Trunk' and other classic fairy tales by H. C. Andersen. Journey into a world of magic and imagination. Read the famous story now!",
    enriched_data: "Dummy data to showcase"
  };

  out.push({
    json: {
      originId,
      type: `${route.type ?? "product" }-metadata`,
      properties,
    },
  });
}

return out;

// Sorts object keys recursively so key order doesn't affect the equality check below
function canonicalize(value) {
  if (Array.isArray(value)) {
    return value.map(canonicalize);
  }
  if (value && typeof value === "object") {
    return Object.keys(value)
      .sort()
      .reduce((acc, key) => {
        acc[key] = canonicalize(value[key]);
        return acc;
      }, {});
  }
  return value;
}

// Check that productMetadata is not empty
const productMetadata = $json.route.productMetadata;

if (
  !productMetadata ||
  Object.keys(productMetadata).length === 0
) {
  throw new Error("productMetadata is empty");
}

// Get source properties
const sourceProperties =
  $('Build Metadata Source Entity').item.json.properties;

// Compare objects regardless of key order
const matches =
  JSON.stringify(canonicalize(sourceProperties)) ===
  JSON.stringify(canonicalize(productMetadata));

if (!matches) {
  throw new Error(
    "Build Metadata Source Entity properties do not match route.productMetadata"
  );
}
